#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
enum NumpyDType {
    // Unsigned integers
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    // Signed integers
    Int8,
    Int16,
    Int32,
    Int64,
    // Floating-point
    Float16,
    Float32,
    Float64,
    // Complex
    Complex64,
    Complex128,
}

/// Returns the bit size of a dtype.
fn dtype_size(dt: NumpyDType) -> u32 {
    match dt {
        // Unsigned integers
        NumpyDType::UInt8 => 8,
        NumpyDType::UInt16 => 16,
        NumpyDType::UInt32 => 32,
        NumpyDType::UInt64 => 64,
        // Signed integers
        NumpyDType::Int8 => 8,
        NumpyDType::Int16 => 16,
        NumpyDType::Int32 => 32,
        NumpyDType::Int64 => 64,
        // Floating-point
        NumpyDType::Float16 => 16,
        NumpyDType::Float32 => 32,
        NumpyDType::Float64 => 64,
        // Complex
        NumpyDType::Complex64 => 64,
        NumpyDType::Complex128 => 128,
    }
}

/// Returns the kind order of a dtype.
/// unsigned int: 0
/// signed int: 1
/// floating-point: 2
/// complex: 3
fn dtype_kind_order(dt: NumpyDType) -> u8 {
    match dt {
        NumpyDType::UInt8
        | NumpyDType::UInt16
        | NumpyDType::UInt32
        | NumpyDType::UInt64 => 0,
        NumpyDType::Int8
        | NumpyDType::Int16
        | NumpyDType::Int32
        | NumpyDType::Int64 => 1,
        NumpyDType::Float16
        | NumpyDType::Float32
        | NumpyDType::Float64 => 2,
        NumpyDType::Complex64
        | NumpyDType::Complex128 => 3,
    }
}

/// Returns whether the given dtype can represent the given integer value.
/// - Unsigned: value must be >= 0 and <= max for bitwidth.
/// - Signed: value must be in -2^(bits-1) ..= 2^(bits-1) - 1
/// - Floating and Complex: always true for integer inputs.
fn can_represent_value(dt: NumpyDType, value: i32) -> bool {
    match dt {
        NumpyDType::UInt8 => (value >= 0) && (value <= u8::MAX as i32),
        NumpyDType::UInt16 => (value >= 0) && (value <= u16::MAX as i32),
        NumpyDType::UInt32 => (value >= 0) && (value <= u32::MAX as i32),  // i32 max < u32 max, so only part of uint32 range
        NumpyDType::UInt64 => (value >= 0), // i32 fits in u64 for nonnegative range 
        NumpyDType::Int8 => value >= i8::MIN as i32 && value <= i8::MAX as i32,
        NumpyDType::Int16 => value >= i16::MIN as i32 && value <= i16::MAX as i32,
        NumpyDType::Int32 => true, // i32 always fits in i32
        NumpyDType::Int64 => true, // i32 fits in i64
        NumpyDType::Float16 => true, // assume float16 can represent any i32 integer for this problem
        NumpyDType::Float32 => true,
        NumpyDType::Float64 => true,
        NumpyDType::Complex64 => true,
        NumpyDType::Complex128 => true,
    }
}

/// Returns the minimal scalar type satisfying the problem conditions:
